"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["82470"],{24289(a){a.exports=JSON.parse('{"id":"F416","slug":"strategy-backtest-metrics","name":"Backtest Performance Metrics","subject":"Quantitative Finance","section":"Quant","topic":"Backtesting trading strategies","level":"Beginner","aliases":["backtesting trading strategies","maximum drawdown","Sharpe ratio of a backtest","Calmar ratio","hit rate"],"formula":{"latex":"R_{ann}=\\\\left(\\\\prod(1+r_{t})\\\\right)^{12/N}-1,\\\\; Sharpe=\\\\frac{12\\\\bar{r}-r_{f}}{\\\\sigma\\\\sqrt{12}},\\\\; MDD=\\\\max\\\\frac{Peak-Value}{Peak},\\\\; Calmar=\\\\frac{R_{ann}}{MDD}","also":[],"text":"Annual return = (product of (1 + monthly return))^(12 / months) - 1; Sharpe = (average monthly return x 12 - risk-free rate) / (monthly sd x sqrt 12); Maximum drawdown = largest fall from a previous peak; Calmar = annual return / maximum drawdown"},"symbols":[{"symbol":"r_t","meaning":"Monthly strategy return","unit":"percent"},{"symbol":"N","meaning":"Number of months","unit":"count"},{"symbol":"r_f","meaning":"Annual risk-free rate","unit":"percent"},{"symbol":"Peak","meaning":"Highest portfolio value so far","unit":"money"},{"symbol":"MDD","meaning":"Maximum drawdown","unit":"percent"}],"when_to_use":"Use it to summarize a backtest in a few numbers. Return and Sharpe show reward per unit of risk, drawdown shows the worst pain an investor would have lived through, and hit rate shows how often the strategy made money. A good backtest result is not proof of a good strategy: look for overfitting, look-ahead bias, survivorship bias and costs before trusting it.","worked_example":{"problem":"A strategy\'s 24 monthly returns are in the calculator. The risk-free rate is 2% a year.","inputs":{"r":[-1.56,1.51,-0.82,1.25,-3.36,-1.23,0.11,3.95,4.81,-3.83,-1.98,3.06,-6.17,-0.82,0.46,5.2,3.21,-0.35,-0.49,-0.08,6.13,-0.7,-0.26,2.03],"rf":2},"steps":[{"label":"Wealth path (starting at 1)","working":null,"value":"1.0000, 0.9844, 0.9993, 0.9911, 1.0035, 0.9697, 0.9578, 0.9589, 0.9967, 1.0447, 1.0047, 0.9848, 1.0149, 0.9523, 0.9445, 0.9488, 0.9982, 1.0302, 1.0266, 1.0216, 1.0208, 1.0833, 1.0757, 1.0730, 1.0947"},{"label":"Final wealth","working":null,"value":"1.0947"},{"label":"Annual return = final^(12 / months) - 1","working":null,"value":"4.63%"},{"label":"Annual volatility = monthly sd x sqrt 12","working":null,"value":"10.24%"},{"label":"Sharpe = (average monthly return x 12 - rf) / annual volatility","working":null,"value":"0.30"},{"label":"Maximum drawdown","working":null,"value":"9.59%"},{"label":"Calmar ratio = annual return / maximum drawdown","working":"0.046295 / 0.0959129","value":"0.48"},{"label":"Hit rate = share of months with a gain","working":null,"value":"45.8%"}],"answer":"The strategy grew 1 to 1.0947, which is 4.63% a year. Annual volatility was 10.24%, giving a Sharpe ratio of 0.30. The worst drawdown was 9.59%, so the Calmar ratio is 0.48. It made money in 45.8% of months."},"calculator":{"available":true,"inputs":[{"id":"r","label":"Monthly returns, oldest first","unit":"%","type":"list","default":[-1.56,1.51,-0.82,1.25,-3.36,-1.23,0.11,3.95,4.81,-3.83,-1.98,3.06,-6.17,-0.82,0.46,5.2,3.21,-0.35,-0.49,-0.08,6.13,-0.7,-0.26,2.03],"hint":""},{"id":"rf","label":"Risk-free rate (annual)","unit":"%","type":"number","default":2,"hint":""}],"checks":[{"expr":"count(r)>=6","message":"Enter at least six monthly returns."}],"steps":[{"id":"w","label":"Wealth path (starting at 1)","expr":"wealth(r)","format":"list4"},{"id":"final","label":"Final wealth","expr":"last(w,1)[0]","format":"num4"},{"id":"ann","label":"Annual return = final^(12 / months) - 1","expr":"final^(12/count(r))-1","format":"pct2"},{"id":"vol","label":"Annual volatility = monthly sd x sqrt 12","expr":"sd(r)*sqrt(12)","format":"pct2"},{"id":"sharpe","label":"Sharpe = (average monthly return x 12 - rf) / annual volatility","expr":"(mean(r)*12-rf)/vol","format":"num2"},{"id":"mdd","label":"Maximum drawdown","expr":"maxdd(w)","format":"pct2"},{"id":"calmar","label":"Calmar ratio = annual return / maximum drawdown","expr":"ann/mdd","format":"num2"},{"id":"hit","label":"Hit rate = share of months with a gain","expr":"sum(1 if x>0 else 0 for x in r)/count(r)","format":"pct1"}],"results":["ann","vol","sharpe","mdd","hit"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"final":1.0947332322616457,"ann":0.04629500250247087,"vol":0.10244427435355323,"sharpe":0.296258626375319,"mdd":0.0959128998172674,"calmar":0.4826775396288903,"hit":0.4583333333333333}},"finder":{"finds":"The headline numbers for a backtest","needs":"A list of periodic returns and the risk-free rate"},"related":[{"slug":"sharpe-ratio","name":"Sharpe Ratio"},{"slug":"maximum-drawdown","name":"Maximum Drawdown"},{"slug":"oos-r-squared","name":"Out-of-Sample R-Squared"}],"related_ids":["F245","F250","F418"],"group":"Risk and quantitative methods","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msub><mi>R</mi><mrow><mi>a</mi><mi>n</mi><mi>n</mi></mrow></msub><mo>=</mo><msup><mrow><mo fence=\\"true\\">(</mo><mo>\u220F</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><msub><mi>r</mi><mi>t</mi></msub><mo stretchy=\\"false\\">)</mo><mo fence=\\"true\\">)</mo></mrow><mrow><mn>12</mn><mi mathvariant=\\"normal\\">/</mi><mi>N</mi></mrow></msup><mo>\u2212</mo><mn>1</mn><mo separator=\\"true\\">,</mo><mtext>\u2005\u200A</mtext><mi>S</mi><mi>h</mi><mi>a</mi><mi>r</mi><mi>p</mi><mi>e</mi><mo>=</mo><mfrac><mrow><mn>12</mn><mover accent=\\"true\\"><mi>r</mi><mo>\u02C9</mo></mover><mo>\u2212</mo><msub><mi>r</mi><mi>f</mi></msub></mrow><mrow><mi>\u03C3</mi><msqrt><mn>12</mn></msqrt></mrow></mfrac><mo separator=\\"true\\">,</mo><mtext>\u2005\u200A</mtext><mi>M</mi><mi>D</mi><mi>D</mi><mo>=</mo><mi>max</mi><mo>\u2061</mo><mfrac><mrow><mi>P</mi><mi>e</mi><mi>a</mi><mi>k</mi><mo>\u2212</mo><mi>V</mi><mi>a</mi><mi>l</mi><mi>u</mi><mi>e</mi></mrow><mrow><mi>P</mi><mi>e</mi><mi>a</mi><mi>k</mi></mrow></mfrac><mo separator=\\"true\\">,</mo><mtext>\u2005\u200A</mtext><mi>C</mi><mi>a</mi><mi>l</mi><mi>m</mi><mi>a</mi><mi>r</mi><mo>=</mo><mfrac><msub><mi>R</mi><mrow><mi>a</mi><mi>n</mi><mi>n</mi></mrow></msub><mrow><mi>M</mi><mi>D</mi><mi>D</mi></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">R_{ann}=\\\\left(\\\\prod(1+r_{t})\\\\right)^{12/N}-1,\\\\; Sharpe=\\\\frac{12\\\\bar{r}-r_{f}}{\\\\sigma\\\\sqrt{12}},\\\\; MDD=\\\\max\\\\frac{Peak-Value}{Peak},\\\\; Calmar=\\\\frac{R_{ann}}{MDD}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"asset-manager-economics","name":"Asset Manager Revenue and Fee Sensitivity"},"next":{"slug":"backtest-performance-summary","name":"Backtest Summary: Return, Risk, Drawdown and Information Ratio"},"lesson":null,"total":522}')}}]);